        </div>
      </div>
    </div>
    <!-- offcanvas ends -->

    <!-- project expenses list -->
    <div v-if="project" class="mt-2">
      <div v-if="loading_spinner" v-html="tableShimmer()"></div>
      <template v-else>
        <NestedAccordion :items="projectExpenses" />
        <p v-if="projectExpenses.length === 0">No Expense recorded for this project !</p>
      </template>
    </div>
    <!-- project expenses list -->

    <div
      class="modal fade mymodal"
      id="project-expenses-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="staticBackdropLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl modal-dialog-scrollable">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="staticBackdropLabel">
              USAGE STATEMENT FOR {{ project_expenses?.description || project_expenses?.name || " " }}
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              id="close"
            ></button>
          </div>
          <div class="modal-body">
            <div class="d-flex me-4 mt-2 my-2">
              <div class="ms-auto">
                <button class="btn btn-success me-2" @click="printItemsReport()">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
                    <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1"/>
                    <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"/>
                  </svg>
                </button>
                <button class="btn btn-primary" @click="add_entry = !add_entry">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
                    <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
                    <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
                  </svg>
                </button>
              </div>
            </div>

            <div class="row mb-4" v-if="add_entry">
              <div class="col-xl-12 col-lg-12 col-sm-12">
                <div class="p-3 border rounded bg-white">
                  <fuelEntryForm
                    :parentId="project_expenses?.id"
                    :groupId="project_expenses?.source_id"
                    :entryId="project_expenses?.entry_id"
                    :rateValue="project_expenses?.unformatedRate"
                    @saved="refreshExpenseItems"
                    @close="add_entry = false"
                  />
                </div>
              </div>
            </div>

            <div class="row layout-top-spacing">
              <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                  <div v-if="loading_spinner" v-html="tableShimmer()"></div>
                  <div v-else class="custom-table table3">
                    <v-client-table
                      :data="projectExpenseItems"
                      :columns="projectExpenseItemsColumns"
                      :options="table_option"
                    >
                    </v-client-table>
                  </div>
                </div>
              </div>
            </div>
          </div>
          <div class="modal-footer">
            <button
              type="button"
              class="btn btn-danger btn-sm py-2 px-2"
              data-bs-dismiss="modal"
              @click="closeModal()"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div>


    <!-- entry registration -->
         <div
      class="modal fade mymodal"
      id="entry-registration-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="staticBackdropLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl modal-dialog-scrollable">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="staticBackdropLabel">
              REGISTRATION FOR NEW EXPENSE GROUP
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              id="close-entry-form"
            ></button>
          </div>
          <div class="modal-body">


              <div class="row">
                 <div class="col-md-12">
                    <input type="text" class="form-control" placeholder="Enter Expense Group Name" v-model="description">
                 </div>
              </div>
          </div>
          <div class="modal-footer">
            <button
              type="button"
              class="btn btn-danger btn-sm py-2 px-2"
              data-bs-dismiss="modal"
              @click="closeModal()"
            >
              Close
            </button>

             <button
              type="submit"
              class="btn btn-primary btn-sm py-2 px-2"
              @click="registerEntry()"
              :disabled="loading"
            >
              <span v-if="loading" v-html="loadingSpinner()"></span>
              <span v-else>Register</span>
            </button>
          </div>
        </div>
      </div>
    </div>
     <!-- entry registration -->
      <!-- entry item registration -->
                <div
      class="modal fade mymodal"
      id="entry-item-registration-modal"
      data-bs-backdrop="false"
      data-bs-keyboard="false"
      tabindex="-1"
      aria-labelledby="staticBackdropLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog modal-xl ">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="staticBackdropLabel">
              REGISTRATION FOR AN ENTRY ITEM
            </h1>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
              id="close-entry-form"
            ></button>
          </div>
          <div class="modal-body">

        <h6 class="text-center">REGISTER PROJECT EXPENSE</h6>
        <div class="row">
    <!-- Expense Type -->
    <div class="col-md-3">
        <label class="form-label small">EXPENSE TYPE</label>

        <multiselect
            v-model="expense_type"
            :options="['GENERAL', 'ASSET']"
            placeholder="Select Expense Type"
            :searchable="false"
            :multiple="false"
            :allow-empty="false"
        />
    </div>

    <!-- Expense -->
    <div class="col-md-5" v-if="expense_type === 'GENERAL'">
        <label class="form-label">Expense</label>

        <input
            type="text"
            class="form-control"
            placeholder="Enter Expense Name"
            v-model="expense_name"
        />
    </div>

    <!-- Asset Category - only for ASSET -->
    <div
        v-if="expense_type === 'ASSET'"
        class="col-md-5"
    >
        <label class="form-label small">
            <span v-if="featchingAssets" v-html="waitIndicator()"></span>
            <span v-else>Asset Category</span>
        </label>

        <multiselect
            v-model="asset_category"
            :options="assetGroups"
            placeholder="Select Asset Group"
            label="name"
            :searchable="true"
            :multiple="false"
            :disabled="featchingAssets"
            :allow-empty="false"
        />
    </div>


          <div class="col-md-2">
            <label class="form-label">Quantity</label>
            <input
              type="text"
              class="form-control"
              placeholder="Enter Quantity"
              v-model="quantity"
              required
            />
          </div>

          <div class="col-md-2">
            <label class="form-label">Rate</label>
            <input
              type="text"
              class="form-control"
              placeholder="Enter Rate"
              v-model="rate"
              required
            />
          </div>
        </div>


          </div>
          <div class="modal-footer">
             <button
            type="button"
            class="btn btn-danger me-3"
                       data-bs-dismiss="modal"

                    id="close_modal"
            @click="
              resetForm();
            "
          >
            Cancel
          </button>
          <button type="submit" @click="registerProjectExpense()" class="btn btn-primary" :disabled="loading">
            <span v-if="loading" class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
            <span v-else>Register</span>
          </button>

          </div>
        </div>
      </div>
