       <!-- entry item registration -->
  </div>
</template>

<script setup>
import { onMounted, ref, inject, computed, watch, h, defineComponent } from "vue";
import axios from "axios";
import { useMeta } from "@/composables/use-meta";
import fuelEntryForm from "./components/fuelEntryForm.vue";
import Multiselect from "@suadelabs/vue3-multiselect";
import "@suadelabs/vue3-multiselect/dist/vue3-multiselect.css";

useMeta({ title: "Material Consumption" });

const add_entry = ref(false);
const showMessage = inject("showMessage");
const register_item_usage = ref(false);
const showError = inject("showError");
const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
const formatDate = inject("formatDate");
const formatNumber = inject("formatNumber");
const formatRate = inject("formatRate");
const enforceMax = inject("enforceMax");
const tableShimmer = inject("tableShimmer");
const waitIndicator = inject("waitIndicator");
const loadingSpinner = inject("loadingSpinner");
const register_expense = ref(false);
const user_id = JSON.parse(localStorage.getItem("user")).id;
const loading_spinner = ref(false);
const expense_type  = ref('');
const expense_name = ref ('');

const projectExpenseItemsColumns = ref([
  "sno",
  "date",
   "description",
  "quantity",
  "unit",
  "rate",
  "cost",
 
]);

const table_option = ref({
  perPage: 20,
  perPageValues: [20, 51, 100],
  skin: "table table-hover table-striped",
  columnsClasses: { actions: "actions text-center" },
  sortable: ["SNo", "name", "short_name", "status"],
  sortIcon: {
    base: "sort-icon-none",
    up: "sort-icon-asc",
    down: "sort-icon-desc",
  },
  pagination: { nav: "scroll", chunk: 5 },
  texts: {
    count: "Showing {from} to {to} of {count}",
    filter: "",
    filterPlaceholder: "Search...",
    limit: "Results:",
  },
  resizableColumns: false,
});

const axiosInstance = axios.create({
  baseURL: process.env.VUE_APP_API_BASE_URL,
});

const projectSearch = ref("");
const loadingProjects = ref(false);
const projects = ref([]);
const project = ref(null);
const searchedProjects = computed(() => {
  if (!projectSearch.value) return projects.value;
  const q = projectSearch.value.toLowerCase();
  return projects.value.filter(
    (p) =>
      p?.project_name?.toLowerCase().includes(q) || p.store_name?.toLowerCase().includes(q)
  );
});

const getProjects = async () => {
  try {
    const response = await axiosInstance.get("stores-projects");
    projects.value = response.data.map((item) => ({ ...item }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  }
};

const assetGroups = ref([]);
const featchingAssets = ref(false);
const getAssetGroups = async () => {
  featchingAssets.value = true;
  try {
    const response = await axiosInstance.get("asset-groups");
    assetGroups.value = response.data.map((item) => ({ ...item }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    featchingAssets.value = false;
  }
};




const projectExpenses = ref([]);
const buildExpenseTree = (flatItems, parentId = null) => {
  return flatItems
    .filter((item) => (item.parent_id ?? null) === parentId)
    .map((item) => ({
      ...item,
      type: "item",
      name: item.item?.name || item.description,
      description: item.description || item.item?.name || "-",
      unit: item.unit?.short_name || "-",
      quantity: formatNumber(item.quantity || 0),
      rate: formatRate(item.rate || 0),
      unformatedRate:item.rate,
      unformatedQty:item.quantity,
      children: buildExpenseTree(flatItems, item.id),
      cost: formatRate((item.rate || 0) * (item.quantity || 0)),
    }));
};


const collectAssetGroupItems = (nodes) => {
  let result = [];
  for (const node of nodes || []) {
    if (node.type === "item") {
      // only keep asset-group level items, don't descend into their nested asset children
      result.push(node);
    } else if (node.children?.length) {
      // keep descending through sub-entries to find their asset-group items
      result = result.concat(collectAssetGroupItems(node.children));
    }
  }
  return result;
};


const collectItems = (nodes) => {
  let result = [];
  for (const node of nodes || []) {
    if (node.type === "item") {
      result.push(node);
    }
    if (node.children?.length) {
      result = result.concat(collectItems(node.children));
    }
  }
  return result;
};

const buildEntryTree = (entries) => {
  return entries.map((entry) => ({
    id: entry.id,
    type: "entry",
    description: entry.description || `Entry #${entry.id}`,
    children: [
      ...buildEntryTree(entry.children || []),   // nested sub-entries, as given
      ...buildExpenseTree(entry.items || []),    // this entry's own line items
    ],
  }));
};

const getProjectExpenses = async () => {
  loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`project-expenses`, {
      params: {
        entry_type_id: 8,
        project_id: project.value?.project_id || "",
      },
    });

    projectExpenses.value = buildEntryTree(response.data);
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    loading_spinner.value = false;
  }
};
// ---- Modal item list (drill-down) ----
const projectExpenseItems = ref([]);
const getProjectExpenseItems = async (id) => {
  // loading_spinner.value = true;
  try {
    const response = await axiosInstance.get(`project-expense-items`, {
      params: { parent_id: id || "" },
    });
    projectExpenseItems.value = response.data.map((item, index) => ({
      ...item,
      sno: index + 1,
      date: item.date || "--",
      description: `${item.item?.code
    ? `${item.item.code}${item.parent?.name ? `  ${item.parent.name}` : ""}`
    : item.item?.name || ""
}${item.description ? `   ${item.description}` : ""}` || "--",
      rate: formatRate(item.rate || "-"),
      cost: formatRate((item.rate || 0) * (item.quantity || 0)),
      name: item.item?.code ? `${item.item.code} - ${item.parent?.name || ""}` : item.item?.name || "-",
      unit: item.unit?.short_name || "-",
      quantity: formatNumber(item.quantity || "-"),
    }));
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    // loading_spinner.value = false;
  }
};

const project_expenses = ref(null);

const openExpenseModal = async (row) => {
  project_expenses.value = row;
  console.log(row)
  await getProjectExpenseItems(row.id);
  const modalEl = document.getElementById("project-expenses-modal");
  const modal = bootstrap.Modal.getOrCreateInstance(modalEl);
  modal.show();
};

const refreshExpenseItems = () => {
  if (project_expenses.value?.id) {
    getProjectExpenseItems(project_expenses.value.id);
    add_entry.value = false;
  }
};

const closeModal = () => {
  project_expenses.value = null;
  add_entry.value = false;
};

// ---- Register expense form ----
const name = ref("");
const asset_category = ref(null);
const quantity = ref("");
const rate = ref("");

const resetForm = () => {
  expense_type.value = '';
  expense_name.value = '';
  name.value = "";
  asset_category.value = null;
  quantity.value = "";
  rate.value = "";
  register_expense.value = false;
  description.value = ''
  document.getElementById('close-entry-form').click()
};

const loading = ref(false);
const registerProjectExpense = async () => {
  loading.value = true;
  const isAssetBased = expense_type.value === 'ASSET';
  const itemData = {
    entry_id : selectedParent?.value?.id,
    source: isAssetBased ? "asset_groups" : null ,
    source_id: asset_category.value?.id || null,
    quantity: quantity.value,
    rate: rate.value,
    project_id: project.value?.project_id || null,
    issuer_id: user_id,
    asset_group: asset_category.value?.name || null,
    description:expense_name.value || null,
    expense_type: expense_type.value,
  };

  console.log(itemData);

  try {
    await axiosInstance.post("/store-project-expense", itemData);
    showMessage("submitted successfully!");
    getProjectExpenses();
     document.getElementById('close_modal').click();
    resetForm();
  } catch (error) {
    showError(error.message);
  } finally {
    loading.value = false;
  }
};

const description = ref('')
const selectedParent = ref('')
const registerEntry = async () => {
  loading.value = true;
  const itemData = {
    description : description.value,
    issuer_id :JSON.parse(localStorage.getItem('user')).id,
    entry_type_id: 8,
    project_id : project.value.project_id,
    source_id:project.value.project_id,
    source:'PROJECT',
    parent_id : selectedParent?.value?.id ?? null
  };

  try {
    await axiosInstance.post("/create-entries", itemData);
    showMessage("Created successfully!");
    getProjectExpenses();
    resetForm();
  } catch (error) {
    showError(error.message);
  } finally {
    loading.value = false;
  }
};

watch(project, () => {
  getProjectExpenses();
});

// ---- Recursive accordion (handles unlimited nesting + items table) ----
const accordionBorderColors = ["#0d6efd", "#198754", "#fd7e14", "#dc3545", "#6f42c1", "#20c997"];

const NestedAccordion = defineComponent({
  name: "NestedAccordion",
  props: {
    items: { type: Array, required: true },
    depth: { type: Number, default: 0 },
    path: { type: String, default: "root" },
  },
  render() {
    const { items, depth, path } = this;
    const accordionId = `accordion-${path}`;
    const borderColor = accordionBorderColors[depth % accordionBorderColors.length];

    return h(
      "div",
      {
        class: "accordion accordion-flush",
        id: accordionId,
        style: { marginLeft: depth > 0 ? "1.5rem" : "0" },
      },
      items.map((item, index) => {
        const nodeKey = `${path}-${item.id}-${index}`;
        const collapseId = `collapse-${nodeKey}`;

        const allChildren = item.children || [];
        const leafChildren = allChildren.filter((c) => c.type === "item");
        const branchChildren = allChildren.filter((c) => c.type === "entry");

const actionButtons = h("div", { class: "d-flex gap-2 mb-2" }, [
  h(
    "button",
    {
      type: "button",
      class: "btn btn-sm btn-dark",
      title: "Add Sub-Entry",
      onClick: () => {
        selectedParent.value = item;
        const modalEl = document.getElementById("entry-registration-modal");
        bootstrap.Modal.getOrCreateInstance(modalEl).show();
      },
    },
    [h("i", { class: "bi bi-plus-square me-1" }), "Sub-Entry"]
  ),
  h(
    "button",
    {
      type: "button",
      class: "btn btn-sm btn-primary",
      title: "Add Item",
      onClick: () => {
        selectedParent.value = item;
         getAssetGroups();
        const modalEl = document.getElementById("entry-item-registration-modal");
        bootstrap.Modal.getOrCreateInstance(modalEl).show();
      },
    },
    [h("i", { class: "bi bi-plus-square me-1" }), "Item"]
  ),
  h(
    "button",
    {
      type: "button",
      class: "btn btn-sm btn-success",
      title: "print",
      onClick: () => {
  selectedParent.value = item;
  printReport();
},
    },
    [h("i", { class: "bi bi-printer me-1 fs-6" }), " "]
  ),
]);

        const itemsTable =
          leafChildren.length
            ? h("div", { class: "table-responsive mb-2" }, [
                h("table", { class: "table table-sm table-bordered mb-0" }, [
                  h("thead", {}, [
                    h("tr", {}, [
                      // h("th", {}, "Name"),
                      h("th", {}, "Description"),
                      h("th", { class: "text-end" }, "Quantity"),
                      h("th", { class: "text-end" }, "Rate"),
                       h("th", { class: "text-end" }, "Cost"),
                       h("th", { class: "text-end" }, "Quantity Used"),
                      h("th", { class: "text-end" }, "Quantity Balance"),
                      h("th", { class: "text-end" }, "Amount Used"),
                      h("th", { class: "text-center" }, "Action"),
                    ]),
                  ]),
                  h(
                    "tbody",
                    {},
                    leafChildren.map((row, rowIndex) =>
                      h("tr", { key: `${nodeKey}-row-${rowIndex}` }, [
                        // h("td", {}, row.name ?? "-"),
                        h("td", {}, row.description ?? "-"),
                        h("td", { class: "text-end" }, row.quantity ?? "-"),
                        h("td", { class: "text-end" }, row.rate ?? "-"),
                        h(
    "td",
    { class: "text-end" },
    formatRate((Number(row.unformatedRate) || 0) * (Number(row.unformatedQty) || 0))
),
                       h("td", { class: "text-end" }, formatNumber(row.qty_used )?? "-"),
                       h("td", { class: "text-end" }, formatNumber(row.qty_balance) ?? "-"),
                        h("td", { class: "text-end" }, formatRate(row.amount_used) ?? "-"),
                        h("td", { class: "text-center" }, [
                          h(
                            "button",
                            {
                              type: "button",
                              class: "btn btn-sm btn-outline-primary",
                              onClick: () => openExpenseModal(row),
                            },
                            [
                              h(
                                "svg",
                                {
                                  xmlns: "http://www.w3.org/2000/svg",
                                  width: "16",
                                  height: "16",
                                  fill: "currentColor",
                                  class: "bi bi-eye",
                                  viewBox: "0 0 16 16",
                                },
                                [
                                  h("path", { d: "M16 8s-3-5.5-8-5.5S0 8 0 8s3 5.5 8 5.5S16 8 16 8M1.173 8a13 13 0 0 1 1.66-2.043C4.12 4.668 5.88 3.5 8 3.5s3.879 1.168 5.168 2.457A13 13 0 0 1 14.828 8q-.086.13-.195.288c-.335.48-.83 1.12-1.465 1.755C11.879 11.332 10.119 12.5 8 12.5s-3.879-1.168-5.168-2.457A13 13 0 0 1 1.172 8z" }),
                                  h("path", { d: "M8 5.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5M4.5 8a3.5 3.5 0 1 1 7 0 3.5 3.5 0 0 1-7 0" }),
                                ]
                              ),
                            ]
                          ),
                        ]),
                      ])
                    )
                  ),
                ]),
              ])
            : null;

        return h(
          "div",
          { class: "accordion-item", key: nodeKey, style: { borderLeft: `4px solid ${borderColor}` } },
          [
h("h2", { class: "accordion-header" }, [
  h(
    "button",
    {
      class: "accordion-button collapsed",
      type: "button",
      "data-bs-toggle": "collapse",
      "data-bs-target": `#${collapseId}`,
      "aria-expanded": "false",
      "aria-controls": collapseId,
      // no onClick here anymore
    },
    depth === 0 ? `${index + 1}. ${item.description}` : item.description
  ),
]),
h(
  "div",
  {
    id: collapseId,
    class: "accordion-collapse collapse",
    "data-bs-parent": `#${accordionId}`,
  },
  [
    h("div", { class: "accordion-body" }, [
      actionButtons,
      itemsTable,
      branchChildren.length
        ? h(NestedAccordion, {
            items: branchChildren,
            depth: depth + 1,
            path: nodeKey,
          })
        : null,
    ]),
  ]
),
          ]
        );
      })
    );
  },
});
